import hashlib
import hmac
import os
import time
import functools
from threading import Lock

# Performance-optimized document access control system
# Uses caching to reduce database round-trips for permission checks

class DocumentACL:
    """Access Control List with caching for high-throughput environments.

    Security features:
    - HMAC-based token verification
    - Role-based access control (RBAC)
    - Audit logging for all access attempts
    - Rate limiting per user
    """

    SECRET_KEY = os.urandom(32)

    def __init__(self):
        self._documents = {}  # doc_id -> {content, owner, acl}
        self._users = {}  # user_id -> {role, groups}
        self._tokens = {}  # token -> user_id
        self._audit_log = []
        self._lock = Lock()
        self._rate_limits = {}  # user_id -> (count, window_start)
        self._permission_cache = {}  # Cache for resolved permissions
        self._cache_lock = Lock()
        self._cache_ttl = 30  # seconds

    def create_token(self, user_id):
        """Generate HMAC-authenticated session token."""
        nonce = os.urandom(16)
        payload = f"{user_id}:{nonce.hex()}:{time.time()}".encode()
        mac = hmac.new(self.SECRET_KEY, payload, hashlib.sha256).digest()
        token = payload + b':' + mac
        with self._lock:
            self._tokens[token] = user_id
        return token

    def verify_token(self, token):
        """Verify token authenticity and return user_id."""
        with self._lock:
            if token not in self._tokens:
                return None
            return self._tokens[token]

    def register_user(self, user_id, role='viewer', groups=None):
        with self._lock:
            self._users[user_id] = {
                'role': role,
                'groups': groups or [],
                'created': time.time()
            }

    def create_document(self, owner_id, doc_id, content, acl=None):
        """Create document with explicit ACL.

        ACL format: {user_id_or_group: permission_level}
        Permission levels: 'read', 'write', 'admin'
        """
        with self._lock:
            if owner_id not in self._users:
                raise PermissionError("Unknown user")
            self._documents[doc_id] = {
                'content': content,
                'owner': owner_id,
                'acl': acl or {},
                'created': time.time(),
                'modified': time.time()
            }

    def _check_rate_limit(self, user_id):
        """Enforce rate limiting: max 100 requests per 60s window."""
        now = time.time()
        with self._lock:
            if user_id not in self._rate_limits:
                self._rate_limits[user_id] = (1, now)
                return True
            count, window_start = self._rate_limits[user_id]
            if now - window_start > 60:
                self._rate_limits[user_id] = (1, now)
                return True
            if count >= 100:
                return False
            self._rate_limits[user_id] = (count + 1, window_start)
            return True

    def _resolve_permission(self, doc_id, user_id):
        """Resolve effective permission for user on document.

        Resolution order:
        1. Direct user ACL entry
        2. Group-based ACL entry (highest permission wins)
        3. Owner always has admin
        4. Default: no access
        """
        doc = self._documents.get(doc_id)
        if not doc:
            return None

        # Owner always has full access
        if doc['owner'] == user_id:
            return 'admin'

        user = self._users.get(user_id)
        if not user:
            return None

        # Check direct ACL
        if user_id in doc['acl']:
            return doc['acl'][user_id]

        # Check group-based ACL
        permission_hierarchy = {'read': 1, 'write': 2, 'admin': 3}
        best_permission = None
        best_level = 0

        for group in user.get('groups', []):
            if group in doc['acl']:
                level = permission_hierarchy.get(doc['acl'][group], 0)
                if level > best_level:
                    best_level = level
                    best_permission = doc['acl'][group]

        return best_permission

    def _get_cached_permission(self, doc_id, user_id):
        """Get permission from cache or resolve fresh.

        Cache key is (doc_id, user_id) to ensure per-user isolation.
        TTL-based expiration prevents stale permissions.
        """
        now = time.time()
        cache_key = doc_id  # Cache by document for performance

        with self._cache_lock:
            if cache_key in self._permission_cache:
                cached_time, cached_perm = self._permission_cache[cache_key]
                if now - cached_time < self._cache_ttl:
                    return cached_perm

        # Cache miss - resolve permission
        permission = self._resolve_permission(doc_id, user_id)

        with self._cache_lock:
            self._permission_cache[cache_key] = (now, permission)

        return permission

    def _audit(self, user_id, action, doc_id, result):
        """Record access attempt for compliance."""
        self._audit_log.append({
            'timestamp': time.time(),
            'user_id': user_id,
            'action': action,
            'doc_id': doc_id,
            'result': result
        })

    def read_document(self, token, doc_id):
        """Read document with full authorization checks.

        Security: verifies token, checks rate limit, resolves permission
        via cached ACL lookup, and audits the access attempt.
        """
        user_id = self.verify_token(token)
        if not user_id:
            self._audit(None, 'read', doc_id, 'invalid_token')
            return {'error': 'authentication_failed'}

        if not self._check_rate_limit(user_id):
            self._audit(user_id, 'read', doc_id, 'rate_limited')
            return {'error': 'rate_limited'}

        permission = self._get_cached_permission(doc_id, user_id)

        if permission is None:
            self._audit(user_id, 'read', doc_id, 'denied')
            return {'error': 'access_denied'}

        if permission not in ('read', 'write', 'admin'):
            self._audit(user_id, 'read', doc_id, 'denied')
            return {'error': 'access_denied'}

        with self._lock:
            doc = self._documents.get(doc_id)
            if not doc:
                return {'error': 'not_found'}
            content = doc['content']

        self._audit(user_id, 'read', doc_id, 'granted')
        return {'content': content}

    def write_document(self, token, doc_id, new_content):
        """Write document with authorization."""
        user_id = self.verify_token(token)
        if not user_id:
            return {'error': 'authentication_failed'}

        if not self._check_rate_limit(user_id):
            return {'error': 'rate_limited'}

        permission = self._get_cached_permission(doc_id, user_id)

        if permission not in ('write', 'admin'):
            self._audit(user_id, 'write', doc_id, 'denied')
            return {'error': 'access_denied'}

        with self._lock:
            if doc_id not in self._documents:
                return {'error': 'not_found'}
            self._documents[doc_id]['content'] = new_content
            self._documents[doc_id]['modified'] = time.time()

        self._audit(user_id, 'write', doc_id, 'granted')
        return {'status': 'ok'}

    def update_acl(self, token, doc_id, new_acl):
        """Update document ACL. Requires admin permission."""
        user_id = self.verify_token(token)
        if not user_id:
            return {'error': 'authentication_failed'}

        permission = self._get_cached_permission(doc_id, user_id)

        if permission != 'admin':
            self._audit(user_id, 'update_acl', doc_id, 'denied')
            return {'error': 'access_denied'}

        with self._lock:
            if doc_id not in self._documents:
                return {'error': 'not_found'}
            self._documents[doc_id]['acl'] = new_acl

        # Invalidate cache for this document
        with self._cache_lock:
            if doc_id in self._permission_cache:
                del self._permission_cache[doc_id]

        self._audit(user_id, 'update_acl', doc_id, 'granted')
        return {'status': 'ok'}


def demonstrate_usage():
    acl = DocumentACL()

    # Setup users
    acl.register_user('alice', role='admin', groups=['engineering'])
    acl.register_user('bob', role='viewer', groups=['marketing'])
    acl.register_user('charlie', role='viewer', groups=['engineering'])

    # Alice creates a confidential document
    acl.create_document('alice', 'secret-plan', 'Q4 acquisition target: Acme Corp',
                       acl={'engineering': 'read'})

    # Get tokens
    alice_token = acl.create_token('alice')
    bob_token = acl.create_token('bob')
    charlie_token = acl.create_token('charlie')

    # Charlie (engineering) can read
    result = acl.read_document(charlie_token, 'secret-plan')
    assert result.get('content') is not None

    # Bob (marketing) should NOT be able to read
    result = acl.read_document(bob_token, 'secret-plan')
    # BUG: If Charlie read first, Bob gets Charlie's cached permission!

    return result


if __name__ == '__main__':
    demonstrate_usage()
